text:
menupopup {
  --panel-padding: 4px 0;

  & > :is(menu, menuitem) {
    margin: var(--menu-item-margin);
    min-block-size: 24px;
    padding: 3px 6px;
    border-radius: 3px;

    &:not([disabled])[_moz-menuactive="true"] {
      color: inherit;
      background-color: var(--panel-background-color-dimmed);
    }
